            for (int i = 0; i < m; ++i) {
                for (int wi = 0; wi < n; ++wi) {
                    int L = words[wi].size();
                    if (i + L <= m) {
                        bool ok = true;
                        for (int k = 0; k < L; ++k)
                            if (s[i + k] != words[wi][k]) { ok = false; break; }
                        if (ok) match[i].push_back(L);
                    }
                }
            }
            // DP to count segmentations
            vector<long long> dp(m + 1, 0);
            dp[0] = 1;
            for (int i = 0; i < m; ++i) {
                if (!dp[i]) continue;
                for (int L : match[i]) {
                    dp[i + L] = (dp[i + L] + dp[i]) % MOD;
                }
            }
            long long hints = dp[m];
            long long ways = hints * hints % MOD;
            total = (total + ways) % MOD;
            return;
        }
        for (int c = 0; c < alpha; ++c) {
            s[pos] = char('a' + c);
            dfs(pos + 1);
        }
    };

    dfs(0);
    cout << total % MOD << '\n';
    return 0;
}

