    }

    // DP for number of tilings of length x using word lengths
    // maxL <= 5, n <= 8, m up to 1e9 -> use linear recurrence with matrix exponentiation
    int K = maxL;
    vector<long long> dp(K + 1);
    dp[0] = 1;
    for (int i = 1; i <= K; ++i) {
        long long s = 0;
        for (int j = 0; j < n; ++j) {
            if (i >= len[j]) {
                s += dp[i - len[j]];
                if (s >= MOD) s -= MOD;
            }
        }
        dp[i] = s;
    }

    // Recurrence: dp[x] = sum_{j} dp[x - len[j]]
    // Express as order-K linear recurrence: f(x) = c1*f(x-1)+...+cK*f(x-K)
    // where ck = number of words of length k
    vector<long long> c(K + 1);
    for (int i = 0; i < n; ++i) c[len[i]]++;

    auto matMul = [&](vector<vector<long long>> &A, vector<vector<long long>> &B) {
        vector<vector<long long>> C(K, vector<long long>(K, 0));
        for (int i = 0; i < K; ++i)
            for (int k = 0; k < K; ++k) if (A[i][k])
                for (int j = 0; j < K; ++j) {
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
                }
        return C;
    };

    auto matVecMul = [&](vector<vector<long long>> &A, vector<long long> &v) {
        vector<long long> r(K, 0);
        for (int i = 0; i < K; ++i)
            for (int j = 0; j < K; ++j)
                r[i] = (r[i] + A[i][j] * v[j]) % MOD;
        return r;
    };

    // Build companion matrix for recurrence
    vector<vector<long long>> M(K, vector<long long>(K, 0));
    for (int j = 0; j < K; ++j) M[0][j] = c[j + 1] % MOD;
    for (int i = 1; i < K; ++i) M[i][i - 1] = 1;

    auto matPow = [&](long long e) {
        vector<vector<long long>> R(K, vector<long long>(K, 0));
        for (int i = 0; i < K; ++i) R[i][i] = 1;
        vector<vector<long long>> B = M;
        while (e > 0) {
            if (e & 1) R = matMul(R, B);
            B = matMul(B, B);
            e >>= 1;
        }
        return R;
    };

    auto get_dp = [&](long long x) -> long long {
        if (x <= K) return dp[x];
        vector<long long> init(K);
        for (int i = 0; i < K; ++i) init[i] = dp[K - i];
        long long e = x - K;
        auto P = matPow(e);
        auto res = matVecMul(P, init);
        return res[0];
    };

    long long Tm = get_dp(m);
    long long ans = Tm * Tm % MOD;
    cout << ans << '\n';
    return 0;
}

