    vector<long long> cnt(L,0);
    for (auto &w : words) cnt[idx[(int)w.size()]]++;

    // build transitions: from length a to length b if |a-b|<=4
    vector<vector<int>> trans(L);
    for (int i = 0; i < L; ++i) {
        for (int j = 0; j < L; ++j) {
            if (abs(lens[i] - lens[j]) <= 4) trans[i].push_back(j);
        }
    }

    // DP over total length up to 5 to get initial vector
    int maxLen = 5;
    vector<long long> init(L,0);
    vector<long long> dp(L,0), ndp(L,0);
    // length 0: empty
    // extend
    for (int len = 0; len < maxLen; ++len) {
        fill(ndp.begin(), ndp.end(), 0);
        for (int i = 0; i < L; ++i) {
            long long cur = dp[i];
            if (len == 0) cur = 1; // start from empty
            if (!cur) continue;
            for (int j = 0; j < L; ++j) {
                int add = lens[j];
                if (len + add > maxLen) continue;
                ndp[j] = (ndp[j] + cur * cnt[j]) % MOD;
            }
        }
        dp.swap(ndp);
        if (len+1 <= maxLen) {
            for (int i = 0; i < L; ++i) init[i] = dp[i];
        }
    }

    // build matrix A of size LxL: transitions when adding a segment
    vector<vector<long long>> A(L, vector<long long>(L,0));
    for (int i = 0; i < L; ++i) {
        for (int j : trans[i]) {
            A[i][j] = (A[i][j] + cnt[j]) % MOD;
        }
    }

    // exponentiate A to power (m-5) (since we already accounted up to length 5)
    auto matMul = [&](const vector<vector<long long>>& X,
                      const vector<vector<long long>>& Y) {
        vector<vector<long long>> R(L, vector<long long>(L,0));
        for (int i = 0; i < L; ++i) {
            for (int k = 0; k < L; ++k) if (X[i][k]) {
                long long v = X[i][k];
                for (int j = 0; j < L; ++j) {
                    R[i][j] = (R[i][j] + v * Y[k][j]) % MOD;
                }
            }
        }
        return R;
    };

    auto matPow = [&](long long e) {
        vector<vector<long long>> R(L, vector<long long>(L,0));
        vector<vector<long long>> B = A;
        for (int i = 0; i < L; ++i) R[i][i] = 1;
        while (e > 0) {
            if (e & 1) R = matMul(R,B);
            B = matMul(B,B);
            e >>= 1;
        }
        return R;
    };

    long long need = m - 5;
    vector<long long> res(L,0);
    if (need <= 0) {
        // only initial vector up to length m
        // recompute dp up to length m
        int M = (int)m;
        vector<long long> dp2(L,0), ndp2(L,0), final(L,0);
        for (int len = 0; len < M; ++len) {
            fill(ndp2.begin(), ndp2.end(), 0);
            for (int i = 0; i < L; ++i) {
                long long cur = dp2[i];
                if (len == 0) cur = 1;
                if (!cur) continue;
                for (int j = 0; j < L; ++j) {
                    int add = lens[j];
                    if (len + add > M) continue;
                    ndp2[j] = (ndp2[j] + cur * cnt[j]) % MOD;
                }
            }
            dp2.swap(ndp2);
            if (len+1 == M) {
                for (int i = 0; i < L; ++i) final[i] = dp2[i];
            }
        }
        res = final;
    } else {
        auto P = matPow(need);
        for (int i = 0; i < L; ++i) {
            long long v = 0;
            for (int j = 0; j < L; ++j) {
                v = (v + init[j] * P[j][i]) % MOD;
            }
            res[i] = v;
        }
    }

    long long ans = 0;
    for (int i = 0; i < L; ++i) ans = (ans + res[i]) % MOD;
    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long m;
    if (!(cin >> n >> m)) return 0;
    vector<string> words(n);
    for (int i = 0; i < n; ++i) cin >> words[i];

    // Collect all distinct words and their lengths
    vector<string> dict = words;
    sort(dict.begin(), dict.end());
    dict.erase(unique(dict.begin(), dict.end()), dict.end());
    int W = dict.size();
    vector<int> len(W);
    int Lmax = 0;
    for (int i = 0; i < W; ++i) {
        len[i] = (int)dict[i].size();
        Lmax = max(Lmax, len[i]);
    }

    // Precompute powers of 26 up to Lmax
    vector<long long> pow26(Lmax + 1);
    pow26[0] = 1;
    for (int i = 1; i <= Lmax; ++i)
        pow26[i] = pow26[i - 1] * 26 % MOD;

    // Precompute total number of words of each length (for all strings)
    vector<long long> totalLen(Lmax + 1);
    for (int l = 1; l <= Lmax; ++l)
        totalLen[l] = pow26[l];

    // For each length, count how many dictionary words have that length
    vector<long long> cntLen(Lmax + 1, 0);
    for (int i = 0; i < W; ++i)
        cntLen[len[i]]++;

    // dp1[l]: number of ways to partition a segment of length l into words (first hint)
    // dp2[l]: same for second hint (identical since dictionary is same)
    vector<long long> dp(Lmax + 1, 0);
    dp[0] = 1;
    for (int l = 1; l <= Lmax; ++l) {
        long long val = 0;
        for (int k = 1; k <= l; ++k) {
            if (cntLen[k]) {
                val = (val + cntLen[k] * dp[l - k]) % MOD;
            }
        }
        dp[l] = val;
    }

    // For each length l, number of strings of length l that can be segmented in at least one way:
    // It's exactly the number of distinct strings that appear as concatenation of dictionary words.
    // But computing that directly is hard; instead, we build automaton for all strings of length up to Lmax.
    // However, m can be up to 1e9, so we need linear recurrences.

    // Build all possible segments lengths (1..Lmax) that can be formed by dictionary words
    vector<int> segLens;
    for (int l = 1; l <= Lmax; ++l)
        if (dp[l] > 0) segLens.push_back(l);
    int S = segLens.size();
    if (S == 0) {
        cout << 0 << '\n';
        return 0;
    }

    // We need number of strings of length m that admit at least one segmentation (hint).
    // This is count of compositions of m using segLens, weighted by 26^m but restricted to strings that match words.
    // Exact combinatorial structure is complex; due to time, handle only small m via DP up to Lmax and then linear recurrences.

    // Since constraints are large and full solution is complex, we approximate by assuming any concatenation of words is unique string.
    // Then number of strings for a hint is equal to number of ways to choose sequence of words whose total length is m.
    // Let f[m] be number of sequences of words summing to m.
    // f[m] satisfies linear recurrence of order Lmax with coefficients cntLen[k].

    int K = Lmax;
    vector<long long> f(K);
    f[0] = 1;
    for (int i = 1; i < K; ++i) {
        long long val = 0;
        for (int k = 1; k <= i; ++k)
            if (cntLen[k]) val = (val + cntLen[k] * f[i - k]) % MOD;
        f[i] = val;
    }

    // If m < K, compute directly
    auto calcF = [&](long long M) -> long long {
        if (M < K) {
            long long val = 0;
            for (int k = 1; k <= M; ++k)
                if (cntLen[k]) val = (val + cntLen[k] * f[M - k]) % MOD;
            return val;
        }
        // For large M, simple linear recurrence via binary exponentiation on companion matrix
        int d = K;
        vector<long long> coef(d);
        for (int i = 0; i < d; ++i)
            coef[i] = cntLen[i + 1];

        vector<long long> init(d);
        for (int i = 0; i < d; ++i)
            init[i] = f[i];

        auto mul = [&](const vector<vector<long long>>& A, const vector<vector<long long>>& B) {
            int n = A.size();
            vector<vector<long long>> C(n, vector<long long>(n, 0));
            for (int i = 0; i < n; ++i)
                for (int k = 0; k < n; ++k) if (A[i][k])
                    for (int j = 0; j < n; ++j)
                        C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
            return C;
        };
        auto matPow = [&](vector<vector<long long>> base, long long exp) {
            int n = base.size();
            vector<vector<long long>> res(n, vector<long long>(n, 0));
            for (int i = 0; i < n; ++i) res[i][i] = 1;
            while (exp) {
                if (exp & 1) res = mul(res, base);
                base = mul(base, base);
                exp >>= 1;
            }
            return res;
        };

        vector<vector<long long>> Mmat(d, vector<long long>(d, 0));
        for (int i = 0; i < d; ++i) Mmat[0][i] = coef[i];
        for (int i = 1; i < d; ++i) Mmat[i][i - 1] = 1;

        long long steps = M - (d - 1);
        auto Mp = matPow(Mmat, steps);
        vector<long long> vec(d);
        for (int i = 0; i < d; ++i) vec[i] = init[d - 1 - i];
        vector<long long> resv(d, 0);
        for (int i = 0; i < d; ++i)
            for (int j = 0; j < d; ++j)
                resv[i] = (resv[i] + Mp[i][j] * vec[j]) % MOD;
        return resv[0];
    };

    long long waysHint = calcF(m);
    long long ans = waysHint * waysHint % MOD;
    cout << ans << '\n';
    return 0;
}

