    int K = lens.size();

    // map length -> index
    unordered_map<int,int> idx;
    for (int i = 0; i < K; ++i) idx[lens[i]] = i;

    // build transition matrix T (K x K)
    vector<vector<long long>> T(K, vector<long long>(K, 0));
    for (int i = 0; i < K; ++i) {
        int L = lens[i];
        for (int j = 0; j < K; ++j) {
            int R = lens[j];
            long long cnt = 0;
            for (auto &w : words) {
                int len = (int)w.size();
                if (len == L || len == R) cnt++;
            }
            T[i][j] = cnt % MOD;
        }
    }

    // matrix multiplication
    auto mul = [&](const vector<vector<long long>> &A,
                   const vector<vector<long long>> &B) {
        vector<vector<long long>> C(K, vector<long long>(K, 0));
        for (int i = 0; i < K; ++i) {
            for (int k = 0; k < K; ++k) if (A[i][k]) {
                long long aik = A[i][k];
                for (int j = 0; j < K; ++j) if (B[k][j]) {
                    C[i][j] = (C[i][j] + aik * B[k][j]) % MOD;
                }
            }
        }
        return C;
    };

    // matrix exponentiation T^(m-1)
    vector<vector<long long>> R(K, vector<long long>(K, 0));
    for (int i = 0; i < K; ++i) R[i][i] = 1;
    vector<vector<long long>> P = T;
    long long e = m - 1;
    while (e > 0) {
        if (e & 1) R = mul(R, P);
        P = mul(P, P);
        e >>= 1;
    }

    // initial vector v0: number of pairs (a,b) with lengths L,R and L+R=m
    vector<long long> v0(K, 0);
    for (int i = 0; i < K; ++i) {
        int L = lens[i];
        int Rlen = (int)m - L;
        if (Rlen <= 0) continue;
        auto it = idx.find(Rlen);
        if (it == idx.end()) continue;
        int j = it->second;
        long long cnt = 0;
        for (auto &w : words) {
            int len = (int)w.size();
            if (len == L || len == Rlen) cnt++;
        }
        v0[i] = cnt % MOD;
    }

    // v = R * v0
    vector<long long> v(K, 0);
    for (int i = 0; i < K; ++i) {
        long long sum = 0;
        for (int j = 0; j < K; ++j) if (R[i][j] && v0[j]) {
            sum = (sum + R[i][j] * v0[j]) % MOD;
        }
        v[i] = sum;
    }

    long long ans = 0;
    for (int i = 0; i < K; ++i) ans = (ans + v[i]) % MOD;
    cout << ans << '\n';
    return 0;
}
